Here's a complete, self-contained Checkout screen for a Telegram Mini App. It's split into three files you'd drop into your project — a types file, the component, and plain CSS. It uses the Telegram WebApp JS SDK (`window.Telegram.WebApp`) for the native `BackButton`/`MainButton` and haptic feedback where available, with sensible fallbacks so it also works outside Telegram during development.

```tsx
// src/types/checkout.ts

export interface CartItem {
  id: string;
  title: string;
  imageUrl?: string;
  price: number;
  quantity: number;
}

export interface DeliveryAddress {
  fullName: string;
  phone: string;
  city: string;
  street: string;
  apartment: string;
  postalCode: string;
  comment: string;
}

export interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  deliveryFee?: number;
  initialAddress?: Partial<DeliveryAddress>;
  isSubmitting?: boolean;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => void;
}

export type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;
```

```tsx
// src/components/CheckoutScreen.tsx

import React, { useEffect, useMemo, useState, useCallback } from 'react';
import type {
  CheckoutScreenProps,
  DeliveryAddress,
  AddressErrors,
} from '../types/checkout';
import './CheckoutScreen.css';

declare global {
  interface Window {
    Telegram?: {
      WebApp?: {
        BackButton: {
          show: () => void;
          hide: () => void;
          onClick: (cb: () => void) => void;
          offClick: (cb: () => void) => void;
        };
        MainButton: {
          text: string;
          color?: string;
          textColor?: string;
          isVisible: boolean;
          isActive: boolean;
          show: () => void;
          hide: () => void;
          enable: () => void;
          disable: () => void;
          showProgress: (leaveActive?: boolean) => void;
          hideProgress: () => void;
          setText: (text: string) => void;
          onClick: (cb: () => void) => void;
          offClick: (cb: () => void) => void;
        };
        HapticFeedback?: {
          impactOccurred: (style: string) => void;
          notificationOccurred: (type: 'error' | 'success' | 'warning') => void;
        };
      };
    };
  }
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

function formatMoney(amount: number, currency: string): string {
  return `${amount.toFixed(2)} ${currency}`;
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Full name is required';
  }

  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required';
  } else if (!/^\+?[0-9\s\-()]{7,20}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }

  if (!address.city.trim()) {
    errors.city = 'City is required';
  }

  if (!address.street.trim()) {
    errors.street = 'Street address is required';
  }

  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required';
  }

  return errors;
}

export default function CheckoutScreen({
  items,
  currency = 'USD',
  deliveryFee = 0,
  initialAddress,
  isSubmitting = false,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>({
    ...EMPTY_ADDRESS,
    ...initialAddress,
  });
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;

  const isFormValid = useMemo(() => {
    const currentErrors = validateAddress(address);
    return Object.keys(currentErrors).length === 0 && items.length > 0;
  }, [address, items.length]);

  const handleChange = useCallback(
    (field: keyof DeliveryAddress) =>
      (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const value = e.target.value;
        setAddress((prev) => ({ ...prev, [field]: value }));
      },
    []
  );

  const handleBlur = useCallback(
    (field: keyof DeliveryAddress) => () => {
      setTouched((prev) => ({ ...prev, [field]: true }));
      setErrors(validateAddress({ ...address }));
    },
    [address]
  );

  const triggerHaptic = useCallback(
    (kind: 'success' | 'error' | 'light') => {
      const haptic = window.Telegram?.WebApp?.HapticFeedback;
      if (!haptic) return;
      if (kind === 'light') {
        haptic.impactOccurred('light');
      } else {
        haptic.notificationOccurred(kind);
      }
    },
    []
  );

  const handlePay = useCallback(() => {
    const currentErrors = validateAddress(address);
    setErrors(currentErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      apartment: true,
      postalCode: true,
      comment: true,
    });

    if (Object.keys(currentErrors).length > 0 || items.length === 0) {
      triggerHaptic('error');
      return;
    }

    triggerHaptic('success');
    onPay(address);
  }, [address, items.length, onPay, triggerHaptic]);

  // Wire up Telegram's native BackButton instead of (or alongside) an in-page button.
  useEffect(() => {
    const webApp = window.Telegram?.WebApp;
    if (!webApp) return;

    webApp.BackButton.show();
    webApp.BackButton.onClick(onBack);

    return () => {
      webApp.BackButton.offClick(onBack);
      webApp.BackButton.hide();
    };
  }, [onBack]);

  // Wire up Telegram's native MainButton as the Pay action.
  useEffect(() => {
    const webApp = window.Telegram?.WebApp;
    if (!webApp) return;

    const mainButton = webApp.MainButton;
    mainButton.setText(
      items.length > 0 ? `Pay ${formatMoney(total, currency)}` : 'Pay'
    );
    mainButton.show();

    if (!isFormValid || isSubmitting) {
      mainButton.disable();
    } else {
      mainButton.enable();
    }

    if (isSubmitting) {
      mainButton.showProgress(true);
    } else {
      mainButton.hideProgress();
    }

    mainButton.onClick(handlePay);

    return () => {
      mainButton.offClick(handlePay);
      mainButton.hide();
    };
  }, [total, currency, isFormValid, isSubmitting, items.length, handlePay]);

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <button
          type="button"
          className="checkout-back-btn"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <span className="checkout-back-icon" aria-hidden="true">
            &#8592;
          </span>
          Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <section className="checkout-section" aria-labelledby="cart-items-heading">
        <h2 id="cart-items-heading" className="checkout-section-title">
          Your order
        </h2>

        {items.length === 0 ? (
          <p className="checkout-empty">Your cart is empty.</p>
        ) : (
          <ul className="checkout-items">
            {items.map((item) => (
              <li key={item.id} className="checkout-item">
                <div className="checkout-item-image-wrap">
                  {item.imageUrl ? (
                    <img
                      className="checkout-item-image"
                      src={item.imageUrl}
                      alt={item.title}
                    />
                  ) : (
                    <div className="checkout-item-image-placeholder" aria-hidden="true" />
                  )}
                </div>
                <div className="checkout-item-info">
                  <span className="checkout-item-title">{item.title}</span>
                  <span className="checkout-item-qty">Qty: {item.quantity}</span>
                </div>
                <span className="checkout-item-price">
                  {formatMoney(item.price * item.quantity, currency)}
                </span>
              </li>
            ))}
          </ul>
        )}

        <div className="checkout-totals">
          <div className="checkout-totals-row">
            <span>Subtotal</span>
            <span>{formatMoney(subtotal, currency)}</span>
          </div>
          <div className="checkout-totals-row">
            <span>Delivery</span>
            <span>
              {deliveryFee > 0 ? formatMoney(deliveryFee, currency) : 'Free'}
            </span>
          </div>
          <div className="checkout-totals-row checkout-totals-row--total">
            <span>Total</span>
            <span>{formatMoney(total, currency)}</span>
          </div>
        </div>
      </section>

      <section className="checkout-section" aria-labelledby="address-heading">
        <h2 id="address-heading" className="checkout-section-title">
          Delivery address
        </h2>

        <form
          className="checkout-form"
          onSubmit={(e) => {
            e.preventDefault();
            handlePay();
          }}
        >
          <div className="checkout-field">
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={handleChange('fullName')}
              onBlur={handleBlur('fullName')}
              className={fieldError('fullName') ? 'checkout-input--error' : ''}
            />
            {fieldError('fullName') && (
              <span className="checkout-field-error">{fieldError('fullName')}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="phone">Phone number</label>
            <input
              id="phone"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={handleChange('phone')}
              onBlur={handleBlur('phone')}
              className={fieldError('phone') ? 'checkout-input--error' : ''}
            />
            {fieldError('phone') && (
              <span className="checkout-field-error">{fieldError('phone')}</span>
            )}
          </div>

          <div className="checkout-field-row">
            <div className="checkout-field">
              <label htmlFor="city">City</label>
              <input
                id="city"
                type="text"
                autoComplete="address-level2"
                value={address.city}
                onChange={handleChange('city')}
                onBlur={handleBlur('city')}
                className={fieldError('city') ? 'checkout-input--error' : ''}
              />
              {fieldError('city') && (
                <span className="checkout-field-error">{fieldError('city')}</span>
              )}
            </div>

            <div className="checkout-field">
              <label htmlFor="postalCode">Postal code</label>
              <input
                id="postalCode"
                type="text"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={handleChange('postalCode')}
                onBlur={handleBlur('postalCode')}
                className={fieldError('postalCode') ? 'checkout-input--error' : ''}
              />
              {fieldError('postalCode') && (
                <span className="checkout-field-error">{fieldError('postalCode')}</span>
              )}
            </div>
          </div>

          <div className="checkout-field">
            <label htmlFor="street">Street address</label>
            <input
              id="street"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={handleChange('street')}
              onBlur={handleBlur('street')}
              className={fieldError('street') ? 'checkout-input--error' : ''}
            />
            {fieldError('street') && (
              <span className="checkout-field-error">{fieldError('street')}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="apartment">Apartment / suite (optional)</label>
            <input
              id="apartment"
              type="text"
              autoComplete="address-line2"
              value={address.apartment}
              onChange={handleChange('apartment')}
            />
          </div>

          <div className="checkout-field">
            <label htmlFor="comment">Delivery notes (optional)</label>
            <textarea
              id="comment"
              rows={3}
              value={address.comment}
              onChange={handleChange('comment')}
              placeholder="E.g. gate code, preferred time, instructions for the courier"
            />
          </div>

          {/*
            Fallback Pay button for environments without Telegram's MainButton
            (e.g. a regular browser during development). Hidden when the Telegram
            WebApp SDK is driving the native MainButton instead.
          */}
          {!window.Telegram?.WebApp && (
            <button
              type="submit"
              className="checkout-pay-btn"
              disabled={!isFormValid || isSubmitting || items.length === 0}
            >
              {isSubmitting
                ? 'Processing...'
                : `Pay ${formatMoney(total, currency)}`}
            </button>
          )}
        </form>
      </section>
    </div>
  );
}
```

